// A FIXTURE EVIDENCE LEDGER, written the way spec 02 §3.2–3.4 says a writer writes one — built IN THE TEST with test-*
// keys generated by node:crypto, so nothing secret is checked in. It hashes and signs on its own (createHash / sign
// over canonicalJson), NOT through src/evidence/hash.ts, so a verifier bug cannot be mirrored by the fixture.
import { createHash, generateKeyPairSync, sign, type KeyObject } from "node:crypto";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { canonicalJson } from "../../src/evidence/canonical.js";

export interface TestKey { readonly kid: string; readonly priv: KeyObject; readonly jwk: { kty: "OKP"; crv: "Ed25519"; x: string } }

/** A root key (`test-*` kid). */
export function testKey(kid: string): TestKey {
  const { privateKey, publicKey } = generateKeyPairSync("ed25519");
  const x = (publicKey.export({ format: "jwk" }) as { x: string }).x;
  return { kid, priv: privateKey, jwk: { kty: "OKP", crv: "Ed25519", x } };
}

/** A writer key: its kid is `wk-` + 24 hex of sha256(x), as gov-check derives it. */
export function writerKey(): TestKey {
  const k = testKey("");
  return { ...k, kid: `wk-${createHash("sha256").update(k.jwk.x).digest("hex").slice(0, 24)}` };
}

const b64u = (s: string | Buffer): string => Buffer.from(s).toString("base64url");
const sigOf = (k: TestKey, text: string): string => sign(null, Buffer.from(text, "utf8"), k.priv).toString("base64url");
const sha = (b: string | Buffer): Buffer => createHash("sha256").update(b).digest();
const noSig = (o: Record<string, unknown>): Record<string, unknown> => { const { sig: _s, ...r } = o; return r; };

/** A lease JWS (EdDSA, typ gov-lease+jws) from `root`, certifying `writer`'s public key in `cnf.jwk`. */
export function leaseJws(root: TestKey, writer: TestKey, claims: Record<string, unknown> = {}, header: Record<string, unknown> = {}): string {
  const h = { alg: "EdDSA", typ: "gov-lease+jws", kid: root.kid, ...header };
  const c = {
    sub: "github-org:297356872", org: { vcs: "github", id: 297356872 }, plan: "pilot", entitlements: ["evidence"],
    cnf: { jwk: writer.jwk }, iat: 1790000000, nbf: 1790000000, exp: 1830000000, jti: `lease-${writer.kid}`, ...claims,
  };
  const input = `${b64u(JSON.stringify(h))}.${b64u(JSON.stringify(c))}`;
  return `${input}.${sign(null, Buffer.from(input), root.priv).toString("base64url")}`;
}

export function record(i: number, over: Record<string, unknown> = {}): Record<string, unknown> {
  return {
    schema: "gov-evidence/1", id: `01JA${String(i).padStart(22, "0")}`, org: { vcs: "github", id: 297356872 }, source: "ci",
    runKey: `gh:9123:1:GOV-ACME-${String(i).padStart(3, "0")}:pull_request`, at: "2026-10-12T09:14:03Z", versions: { gov: "2.0.0" },
    kind: "check", repo: { id: 77, name: "acme/app" }, rule: { id: `GOV-ACME-${String(i).padStart(3, "0")}` },
    verdict: "pass", class: "prevented", messageKey: "landed-by-pr.ok", ...over,
  };
}

export function gapRecord(i: number, over: Record<string, unknown> = {}): Record<string, unknown> {
  return {
    schema: "gov-evidence/1", id: `01JB${String(i).padStart(22, "0")}`, org: { vcs: "github", id: 297356872 }, source: "local",
    runKey: `local:01JB${String(i).padStart(22, "0")}:GOV-ACME-001`, at: "2026-10-13T10:00:00Z", versions: { gov: "2.0.0" },
    kind: "gap", reason: "lease.expired", ...over,
  };
}

export interface SegSpec {
  /** `2026/10/12` */
  readonly date: string;
  readonly name: string;
  readonly records: readonly Record<string, unknown>[];
  readonly writer?: TestKey;
}

export interface Ledger {
  readonly dir: string;
  readonly root: TestKey;
  readonly writer: TestKey;
  /** Relative to dir, e.g. `evidence/2026/10/12/ci-77-1-1.jsonl`. */
  readonly segments: string[];
  readonly entries: Record<string, unknown>[];
  /** Overwrite a file of the ledger (relative path). */
  write(rel: string, text: string): void;
  read(rel: string): string;
  cleanup(): void;
}

/**
 * Write segments in order and chain them: entry n links to entry n-1 across month files; each segment's seal records
 * the head its writer saw. The chain month is the segment's date month.
 */
export function buildLedger(segs: readonly SegSpec[], opts: { root?: TestKey; writer?: TestKey; extraWriters?: readonly { key: TestKey; leases: readonly string[] }[]; gaps?: readonly { date: string; name: string; records: readonly Record<string, unknown>[] }[] } = {}): Ledger {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "gov-ledger-"));
  const root = opts.root ?? testKey("test-root-1");
  const writer = opts.writer ?? writerKey();
  const put = (rel: string, text: string): void => { const f = path.join(dir, rel); fs.mkdirSync(path.dirname(f), { recursive: true }); fs.writeFileSync(f, text); };
  put("evidence/README.md", "# evidence\n");
  put("evidence/keys/roots.json", `${JSON.stringify({ keys: [{ kid: root.kid, ...root.jwk }] }, null, 2)}\n`);
  const writers = new Map<string, TestKey>([[writer.kid, writer]]);
  put(`evidence/keys/${writer.kid}.json`, `${JSON.stringify({ kid: writer.kid, jwk: writer.jwk, leases: [leaseJws(root, writer)] })}\n`);
  for (const w of opts.extraWriters ?? []) {
    writers.set(w.key.kid, w.key);
    put(`evidence/keys/${w.key.kid}.json`, `${JSON.stringify({ kid: w.key.kid, jwk: w.key.jwk, leases: w.leases })}\n`);
  }

  const segments: string[] = [];
  const entries: Record<string, unknown>[] = [];
  const months = new Map<string, string[]>();
  let head = "0".repeat(64);
  for (const s of segs) {
    const w = s.writer ?? writer;
    const rootHash = createHash("sha256");
    for (const r of s.records) rootHash.update(sha(canonicalJson(r)));
    const seal: Record<string, unknown> = { segment: s.name, count: s.records.length, root: rootHash.digest("hex"), chainPrev: head, writer: w.kid, cert: `lease-${w.kid}` };
    seal.sig = sigOf(w, canonicalJson(seal));
    const text = [...s.records.map((r) => canonicalJson(r)), canonicalJson({ seal })].join("\n") + "\n";
    const rel = `evidence/${s.date}/${s.name}.jsonl`;
    put(rel, text);
    segments.push(rel);
    const entry: Record<string, unknown> = { n: entries.length + 1, segment: `${s.date}/${s.name}.jsonl`, sha256: sha(text).toString("hex"), prev: head, writer: w.kid };
    entry.sig = sigOf(w, canonicalJson(entry));
    entries.push(entry);
    head = sha(canonicalJson(entry)).toString("hex");
    const month = s.date.slice(0, 7).replace("/", "-");
    months.set(month, [...(months.get(month) ?? []), canonicalJson(entry)]);
  }
  for (const [m, lines] of months) put(`evidence/chain/${m}.jsonl`, lines.join("\n") + "\n");
  for (const g of opts.gaps ?? []) put(`evidence/${g.date}/${g.name}.jsonl`, g.records.map((r) => canonicalJson(r)).join("\n") + "\n");
  void writers;

  return {
    dir, root, writer, segments, entries,
    write: put,
    read: (rel) => fs.readFileSync(path.join(dir, rel), "utf8"),
    cleanup: () => fs.rmSync(dir, { recursive: true, force: true }),
  };
}

/** Re-sign an entry with its writer after a test edits it (to prove the `prev` check, not the signature, catches it). */
export function resignEntry(entry: Record<string, unknown>, w: TestKey): Record<string, unknown> {
  const e = noSig(entry);
  return { ...e, sig: sigOf(w, canonicalJson(e)) };
}
